            "label": "Date of adoption: 26th November 1949 (Constitution Day).\nTRAP: The date of commencement is 26th January 1950, but the Preamble states the date of adoption by the Constituent Assembly.\nThe Preamble was enacted after the rest of the Constitution was already passed.",
            "kind": "bullet"
